@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#080b10;--paper:#e4e6df;--muted:#8a9295;--red:#e45148;--cyan:#7bc9c2;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;background:#05070a;color:var(--paper);overflow:hidden}body{font-family:var(--mono)}button{font:inherit;color:inherit}.game-shell{position:relative;width:min(100vw,calc(100vh * 16 / 9));height:min(100vh,calc(100vw * 9 / 16));margin:auto;top:50%;transform:translateY(-50%);overflow:hidden;background:#080b10;box-shadow:0 0 100px #000;isolation:isolate}canvas{display:block;width:100%;height:100%;image-rendering:auto}.scanlines{pointer-events:none;position:absolute;inset:0;z-index:5;opacity:.13;background:linear-gradient(transparent 50%,rgba(0,0,0,.2) 50%);background-size:100% 4px;mix-blend-mode:multiply}.scanlines:after{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at center,transparent 42%,rgba(0,0,0,.58) 110%)}.screen{position:absolute;inset:0;z-index:10;background:rgba(5,8,13,.83);backdrop-filter:blur(4px)}.hidden{display:none!important}.title-screen{display:flex;flex-direction:column;justify-content:space-between;padding:4.7% 6.3%;background:linear-gradient(90deg,rgba(5,8,13,.96) 0%,rgba(5,8,13,.79) 44%,rgba(5,8,13,.1) 100%),linear-gradient(0deg,rgba(5,8,13,.64),transparent 30%),url('')}.title-top,.title-bottom{display:flex;align-items:center;justify-content:space-between;font-size:10px;letter-spacing:.18em;color:#9da4a5}.title-top b{color:#e2e4df;font-weight:400}.brand-mark{font:800 27px var(--display);color:#e9e9df;border:1px solid #676f70;width:42px;height:42px;display:grid;place-items:center;letter-spacing:-.08em}.brand-mark span{color:var(--red)}.title-copy{margin-top:-1.5%;max-width:570px}.eyebrow{font-size:10px;letter-spacing:.2em;color:var(--cyan);margin:0 0 16px}.eyebrow i{display:inline-block;width:6px;height:6px;background:var(--red);margin-right:8px;box-shadow:0 0 10px var(--red)}h1,h2{font-family:var(--display);font-weight:700;letter-spacing:.035em;line-height:.77;margin:0}h1{font-size:clamp(72px,10.5vw,142px)}h1 span{color:var(--red)}h1 em,h2 em{font-style:normal;color:#aab1ae;font-weight:500}.title-desc{color:#a7adab;font-size:12px;line-height:1.9;margin:27px 0 30px}.primary-button{display:flex;align-items:center;gap:46px;padding:14px 16px 13px;background:var(--red);border:0;color:#101214;font-size:11px;letter-spacing:.16em;font-weight:500;cursor:pointer;transition:.2s;min-width:240px;justify-content:space-between}.primary-button:hover{background:#ff7166;transform:translateY(-2px);box-shadow:0 8px 26px #e4514840}.primary-button b{font-size:17px}.title-hint{margin-top:19px;color:#798183;font-size:9px;letter-spacing:.13em}.title-bottom{font-size:9px}.title-bottom i{font-style:normal;color:var(--red);font-size:7px;margin-left:10px}.briefing{display:grid;grid-template-columns:1fr 30%;background:linear-gradient(90deg,rgba(5,8,13,.98),rgba(7,11,16,.91) 68%,rgba(7,11,16,.55))}.brief-card{align-self:center;margin-left:12%;max-width:540px}.brief-kicker{display:flex;justify-content:space-between;color:#aab1b0;font-size:10px;letter-spacing:.17em}.brief-kicker span{color:#687173}.brief-line{height:1px;background:#42494b;margin:14px 0 34px}.brief-card h2,.pause-card h2,.end-card h2{font-size:clamp(54px,7vw,86px);margin-bottom:28px}.brief-text{font-size:12px;line-height:1.9;color:#c1c6c1;max-width:460px}.brief-text strong{color:white;font-weight:500}.brief-text.dim{color:#81898a}.brief-text i{color:#d8d9d2;font-style:normal}.text-button{background:none;border:0;border-bottom:1px solid #626b6c;padding:15px 0 9px;margin-top:18px;color:var(--cyan);font-size:10px;letter-spacing:.18em;cursor:pointer}.text-button span{font-size:17px;margin-left:32px}.brief-aside{align-self:center;justify-self:center;display:flex;flex-direction:column;gap:20px;color:#818a8c;font-size:9px;line-height:1.8;letter-spacing:.15em}.crosshair{font-size:54px;color:#445151;font-family:var(--display);font-weight:300}.hud{position:absolute;inset:0;z-index:6;pointer-events:none}.hud-top{position:absolute;left:4.2%;right:4.2%;top:4.1%;display:flex;align-items:flex-start;justify-content:space-between;text-shadow:0 2px 6px #000}.hud-brand{display:flex;gap:10px;align-items:center}.mini-mark{width:30px;height:30px;display:grid;place-items:center;border:1px solid #6b7474;font:700 19px var(--display);color:var(--cyan)}.hud-brand b,.hud-brand small,.objective small,.objective b,.sector small,.sector b{display:block}.hud-brand b{font:600 16px var(--display);letter-spacing:.15em}.hud-brand small,.objective small,.sector small{font-size:8px;color:#9ca4a3;letter-spacing:.13em;margin-top:3px}.objective{position:absolute;left:50%;transform:translateX(-50%);text-align:center;border-top:1px solid #89929288;padding:8px 25px 0}.objective b{font-size:11px;letter-spacing:.11em;margin-top:4px}.sector{text-align:right}.sector b{font-size:11px;letter-spacing:.1em;margin-top:4px}.hud-bottom{position:absolute;left:4.2%;right:4.2%;bottom:4.5%;display:flex;align-items:center;gap:28px;text-shadow:0 2px 6px #000}.vitals{display:grid;grid-template-columns:auto 130px 28px;align-items:center;gap:9px}.hud-label{font-size:8px;letter-spacing:.13em;color:#aab1af}.health-track{height:4px;background:#323a3d;overflow:hidden}.health-track i{height:100%;display:block;width:100%;background:var(--red);transition:width .2s}.vitals>b{font-size:11px;font-weight:400}.ammo{display:flex;align-items:baseline;gap:5px;border-left:1px solid #657071;padding-left:22px}.ammo-icon{font-size:14px;color:var(--cyan);margin-right:3px}.ammo>b{font:600 20px var(--display)}.ammo small{font-size:10px;color:#90999a}.ammo .hud-label{margin-left:7px}.collectibles,.medkits{margin-left:auto;display:flex;align-items:baseline;gap:8px}.collectibles b,.medkits b{font:600 20px var(--display);color:var(--cyan)}.collectibles span:not(.hud-label),.medkits span:not(.hud-label){font-size:10px;color:#91999a}.medkits{margin-left:2px}.crosshair-ui{position:absolute;width:18px;height:18px;border:1px solid #f1e8c8;border-radius:50%;opacity:.8;transform:translate(-50%,-50%);display:none}.crosshair-ui:after{content:'';position:absolute;width:3px;height:3px;background:var(--red);border-radius:50%;left:6.5px;top:6.5px}.toast{position:absolute;top:18%;left:50%;transform:translateX(-50%);padding:10px 18px;background:#090e13d9;border-left:2px solid var(--red);font-size:10px;letter-spacing:.09em;color:#e5e6db;opacity:0;transition:opacity .3s}.toast.show{opacity:1}.interact-prompt{position:absolute;left:50%;top:75%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:9px;color:#e4e7df;font-size:9px;letter-spacing:.13em;text-shadow:0 2px 5px #000}.interact-prompt kbd{font:11px var(--mono);padding:6px 9px;border:1px solid #d1d6cd;background:#0a0c0ed9}.controls-hint{position:absolute;right:4.2%;bottom:5.2%;font-size:8px;color:#727b7d;letter-spacing:.08em}.controls-hint span{color:#d2d7d2;margin-left:10px}.story-caption{position:absolute;z-index:8;bottom:14%;left:50%;transform:translateX(-50%);width:min(590px,80%);padding:15px 20px 17px;background:linear-gradient(90deg,#090d11ed,#101519e8);border-left:2px solid var(--cyan);box-shadow:0 8px 35px #0008}.caption-speaker{font-size:9px;color:var(--cyan);letter-spacing:.15em;margin-bottom:8px}.caption-speaker span{color:#778181}.story-caption p{font-size:12px;line-height:1.65;color:#e1e4dc;margin:0}.caption-progress{position:absolute;bottom:0;left:0;right:0;height:2px;background:#363e3f}.caption-progress i{height:100%;display:block;width:0;background:var(--cyan)}.pause-screen,.end-screen{display:grid;place-items:center;background:rgba(4,7,10,.78)}.pause-card,.end-card{width:min(430px,80%);padding:38px;background:#0b1015ed;border:1px solid #404849;box-shadow:0 20px 90px #000}.pause-card h2,.end-card h2{font-size:65px;margin-bottom:20px}.pause-card>p:not(.eyebrow),.end-card>p:not(.eyebrow){font-size:11px;color:#9da6a4;line-height:1.7;margin-bottom:24px}.pause-controls{border-top:1px solid #373e40;margin-top:24px;padding-top:16px;font-size:9px;line-height:2;color:#7e8788;letter-spacing:.08em}.end-card{text-align:left}.end-card .primary-button{margin-top:30px}.mobile-controls{position:absolute;z-index:7;inset:auto 0 5% 0;pointer-events:none;justify-content:space-between;padding:0 5%}.dpad,.mobile-actions{pointer-events:auto}.dpad button,.mobile-actions button{background:#141c20b8;border:1px solid #91a09c75;color:#edf2e8;width:43px;height:40px;font-size:13px;border-radius:4px;touch-action:none}.dpad>div{display:flex;gap:2px}.mobile-actions{display:flex;gap:10px;align-items:flex-end}.mobile-actions button{width:65px;height:55px;color:var(--red);font:10px var(--mono);letter-spacing:.1em}.mobile-actions button:last-child{color:var(--cyan)}
@media(max-width:700px){.game-shell{width:100vw;height:100dvh;top:0;transform:none}.title-screen{padding:7% 7% 9%}.title-top,.title-bottom{font-size:8px}.title-copy{margin-top:0}.title-desc{font-size:11px}.briefing{grid-template-columns:1fr}.brief-card{margin:0 8%;}.brief-aside{display:none}.brief-card h2{font-size:58px}.hud-top{top:3%;left:5%;right:5%}.hud-brand small{font-size:6px}.objective{top:50px;width:210px;padding:6px 5px}.objective small,.sector small{font-size:7px}.objective b,.sector b{font-size:9px}.sector{margin-top:1px}.hud-bottom{left:5%;right:5%;bottom:17%;gap:12px;flex-wrap:wrap}.vitals{grid-template-columns:auto 75px 22px;gap:6px}.hud-label{font-size:7px}.ammo{padding-left:12px}.collectibles{margin-left:auto}.medkits{margin-left:5px}.controls-hint{display:none}.mobile-controls{display:flex}.story-caption{bottom:29%;width:88%;padding:12px 14px}.story-caption p{font-size:11px}.interact-prompt{top:67%}.pause-card,.end-card{padding:27px}.pause-card h2,.end-card h2{font-size:55px}}@media(hover:none){.crosshair-ui{display:none!important}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 1280, H = 720, FLOOR = 610, WORLD = 4320;
  canvas.width = W; canvas.height = H;
  const $ = id => document.getElementById(id);
  const ui = {title:$('titleScreen'),brief:$('briefing'),hud:$('hud'),pause:$('pauseScreen'),end:$('endScreen'),caption:$('caption'),prompt:$('interactPrompt'),toast:$('toast'),objective:$('objectiveText'),sector:$('sectorText'),health:$('healthBar'),healthValue:$('healthValue'),ammo:$('ammoValue'),cores:$('coreCount'),med:$('medCount'),speaker:$('captionSpeaker'),captionText:$('captionText'),progress:document.querySelector('.caption-progress i'), mobile:$('mobileControls'),aim:$('aimDot')};
  const input={keys:new Set(),mouse:{x:W*.65,y:H*.5,down:false},touch:new Set(),mobileFire:false};
  let state='title', last=0, time=0, cam=0, toastTimer=0, captionTimer=0, shotCooldown=0, spawnTimer=0, screenShake=0, muted=false;
  const player={x:120,y:FLOOR-62,vx:0,vy:0,w:34,h:62,hp:100,ammo:12,reserve:48,med:1,facing:1,grounded:true,invuln:0,flash:0};
  const terminals=[{x:520,type:'relay',used:false,label:'RELÉ DE ENERGÍA',sector:'ESCLUSA 01'},{x:1460,type:'core',used:false,label:'NÚCLEO DE DATOS A',sector:'LABORATORIO'},{x:2460,type:'core',used:false,label:'NÚCLEO DE DATOS B',sector:'CRIOGENIA'},{x:3350,type:'core',used:false,label:'NÚCLEO DE DATOS C',sector:'HABITÁCULOS'},{x:4050,type:'exit',used:false,label:'CÁPSULA DE ESCAPE',sector:'ESCLUSA 04'}];
  const enemies=[],bullets=[],enemyShots=[],particles=[],pickups=[];
  const debris=[...Array(55)].map((_,i)=>({x:(i*173+91)%WORLD,y:40+(i*79)%440,r:1+(i%3)*.65,a:.13+(i%5)*.045}));
  let cores=0,relay=false,kills=0,runEnd=false;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const rand=(a,b)=>a+Math.random()*(b-a);
  function sound(freq=180,dur=.08,type='square',vol=.025){try{const ac=sound.ac||(sound.ac=new(window.AudioContext||window.webkitAudioContext)());const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(freq,ac.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,freq*.48),ac.currentTime+dur);g.gain.setValueAtTime(vol,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+dur);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+dur)}catch(e){}}
  function showToast(text,duration=2500){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=duration;}
  function caption(speaker,text,duration=4800){ui.speaker.innerHTML=`${speaker} <span>// ${speaker==='VERA SOLÍS'?'TRAJE':'REGISTRO'}</span>`;ui.captionText.textContent=text;ui.caption.classList.remove('hidden');ui.progress.style.transition='none';ui.progress.style.width='0';requestAnimationFrame(()=>{ui.progress.style.transition=`width ${duration}ms linear`;ui.progress.style.width='100%'});captionTimer=duration;}
  function hideCaption(){ui.caption.classList.add('hidden');}
  function begin(){state='brief';ui.title.classList.add('hidden');ui.brief.classList.remove('hidden'); sound(110,.2,'sine');}
  function enterGame(){state='playing';ui.brief.classList.add('hidden');ui.hud.classList.remove('hidden');ui.mobile.classList.toggle('hidden',!('ontouchstart'in window));caption('VERA SOLÍS','Control, estoy dentro. La estación está… congelada. No veo señales térmicas.');showToast('OBJETIVO ACTUALIZADO  //  RESTAURA LA ENERGÍA');}
  function setEnd(win){state='end';ui.hud.classList.add('hidden');ui.caption.classList.add('hidden');ui.end.classList.remove('hidden');$('endKicker').textContent=win?'TRANSMISIÓN ENVIADA // 2189':'REGISTRO DE BAJA // NÁYADE';$('endTitle').innerHTML=win?'LA SEÑAL<br><em>SIGUE VIVA.</em>':'EL VACÍO<br><em>TE RECLAMA.</em>'; $('endText').textContent=win?'La cápsula se aleja de NÁYADE. En la grabación, algo golpea desde dentro del núcleo que rescataste. La señal de socorro nunca fue para pedir ayuda.':'La estación guarda silencio otra vez. Pero en algún lugar, bajo el hielo de Europa, algo acaba de aprender tu nombre.';sound(win?420:80,.5,'sawtooth',.04);}
  function restart(){location.reload();}
  $('startButton').addEventListener('click',begin);$('briefContinue').addEventListener('click',enterGame);$('resumeButton').addEventListener('click',()=>{state='playing';ui.pause.classList.add('hidden');last=performance.now()});$('restartButton').addEventListener('click',restart);
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();input.keys.add(k);if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'&&state==='playing'){state='paused';ui.pause.classList.remove('hidden')}else if(k==='escape'&&state==='paused'){$('resumeButton').click()}if(k==='e'&&state==='playing')interact();if(k==='q'&&state==='playing')useMed();if(k==='r'&&state==='playing'&&player.ammo<12)reload();});
  window.addEventListener('keyup',e=>input.keys.delete(e.key.toLowerCase()));
  canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();input.mouse.x=(e.clientX-r.left)/r.width*W;input.mouse.y=(e.clientY-r.top)/r.height*H;ui.aim.style.left=`${e.clientX-r.left}px`;ui.aim.style.top=`${e.clientY-r.top}px`});
  canvas.addEventListener('pointerdown',e=>{if(state!=='playing')return;input.mouse.down=true;canvas.setPointerCapture?.(e.pointerId)});window.addEventListener('pointerup',()=>input.mouse.down=false);
  function bindTouchButton(el,down,up=()=>{}){el.addEventListener('pointerdown',e=>{e.preventDefault();down();el.setPointerCapture?.(e.pointerId)});el.addEventListener('pointerup',e=>{e.preventDefault();up()});el.addEventListener('pointercancel',up)}
  document.querySelectorAll('[data-key]').forEach(b=>bindTouchButton(b,()=>input.touch.add(b.dataset.key),()=>input.touch.delete(b.dataset.key)));
  bindTouchButton($('mobileFire'),()=>input.mobileFire=true,()=>input.mobileFire=false);$('mobileUse').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
  function reload(){if(player.ammo>=12||player.reserve<=0)return;const n=Math.min(12-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;showToast('RECARGANDO // CARGADOR DE PULSO');sound(90,.12,'square');}
  function useMed(){if(player.med<=0||player.hp>=100)return;player.med--;player.hp=Math.min(100,player.hp+42);showToast('BOTIQUÍN APLICADO // +42 INTEGRIDAD');sound(520,.12,'sine');updateHud()}
  function currentTerminal(){return terminals.find(t=>!t.used&&Math.abs(t.x-player.x)<82)}
  function interact(){if(state!=='playing')return;const t=currentTerminal();if(!t)return;if(t.type==='relay'){t.used=true;relay=true;ui.objective.textContent='RECUPERA LOS 3 NÚCLEOS';caption('VERA SOLÍS','Energía restaurada. Espera… ¿ese pulso viene de los conductos?');showToast('RELÉ RESTAURADO // NÚCLEO A LOCALIZADO');spawnEnemy(710,'stalker');spawnEnemy(870,'crawler');sound(260,.3,'sine',.04)}else if(t.type==='core'){if(!relay){showToast('SIN ENERGÍA // ACTIVA EL RELÉ PRIMERO');return}t.used=true;cores++;ui.cores.textContent=cores;ui.objective.textContent=cores<3?`RECUPERA LOS 3 NÚCLEOS  //  ${cores}/3`:'LLEGA A LA CÁPSULA DE ESCAPE';caption('VERA SOLÍS',coreStory(cores),5800);showToast(`NÚCLEO RECUPERADO  //  ${cores} DE 3`);sound(430,.22,'sine',.04);if(cores===3){terminals[4].used=false;spawnEnemy(player.x+280,'brute')}}else if(t.type==='exit'){if(cores<3){showToast('CÁPSULA BLOQUEADA // FALTAN NÚCLEOS');return}t.used=true;caption('VERA SOLÍS','Control, tengo los núcleos. No… hay algo en la cápsula. La señal de socorro viene de aquí.',3800);setTimeout(()=>{if(state==='playing')setEnd(true)},3600)}}
  function coreStory(n){return n===1?'Esto es el registro de la doctora Imani: el organismo llegó en la sonda Orfeo. No era un parásito. Era una colonia dormida, adaptada al vacío.' : n===2?'Los congelaron para estudiarlos. El calor los despertó. Se anclaron al sistema nervioso y copiaron recuerdos… por eso usaban nuestras voces.':'La colonia no infectó a la tripulación para alimentarse. Construyó una mente colectiva. La señal de auxilio… es un señuelo para que alguien la saque de aquí.'}
  function updateHud(){ui.health.style.width=`${player.hp}%`;ui.healthValue.textContent=Math.ceil(player.hp);ui.ammo.textContent=player.ammo;ui.med.textContent=player.med;ui.cores.textContent=cores;}
  function spawnEnemy(x,type){if(enemies.filter(e=>e.hp>0).length>=9)return;const t=type||(['crawler','stalker','crawler'][Math.floor(Math.random()*3)]);enemies.push({x:clamp(x,30,WORLD-50),y:FLOOR-52,w:t==='brute'?54:40,h:t==='crawler'?36:52,hp:t==='brute'?6:t==='stalker'?3:2,max:t==='brute'?6:t==='stalker'?3:2,type:t,vx:0,attack:rand(.3,1.3),flash:0,phase:rand(0,7),dir:1});}
  function shoot(){if(shotCooldown>0)return;if(player.ammo<=0){showToast('CARGADOR VACÍO // [R] RECARGAR',1300);shotCooldown=.35;sound(80,.08);return}player.ammo--;shotCooldown=.24;player.flash=.08;screenShake=2;const px=player.x+player.w/2,py=player.y+22;let tx=input.mouse.x+cam,ty=input.mouse.y; if(input.mobileFire){const target=enemies.filter(e=>e.hp>0).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0];if(target){tx=target.x;ty=target.y-20}else{tx=px+player.facing*300;ty=py-20}}
    let dx=tx-px,dy=ty-py;const d=Math.hypot(dx,dy)||1;dx/=d;dy/=d;if(Math.abs(dx)>.15)player.facing=Math.sign(dx);bullets.push({x:px+dx*20,y:py+dy*10,vx:dx*790,vy:dy*790,life:.8});sound(210,.065,'sawtooth',.025);updateHud()}
  function damagePlayer(amount){if(player.invuln>0)return;player.hp=Math.max(0,player.hp-amount);player.invuln=.7;screenShake=10;player.vx-=player.facing*130;updateHud();sound(75,.18,'sawtooth',.04);if(player.hp<=0)setEnd(false)}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-150,150),vy:rand(-190,80),life:rand(.2,.6),max:.6,color,size:rand(2,5)})}
  function update(dt){time+=dt;shotCooldown=Math.max(0,shotCooldown-dt);if(toastTimer>0&&(toastTimer-=dt*1000)<=0)ui.toast.classList.remove('show');if(captionTimer>0&&(captionTimer-=dt*1000)<=0)hideCaption();if(player.invuln>0)player.invuln-=dt;if(player.flash>0)player.flash-=dt;screenShake=Math.max(0,screenShake-dt*24);
    const left=input.keys.has('a')||input.keys.has('arrowleft')||input.touch.has('left'),right=input.keys.has('d')||input.keys.has('arrowright')||input.touch.has('right'),up=input.keys.has('w')||input.keys.has('arrowup')||input.touch.has('up'),down=input.keys.has('s')||input.keys.has('arrowdown')||input.touch.has('down');
    const axis=(right?1:0)-(left?1:0);if(axis){player.vx+=axis*1700*dt;player.facing=axis}else player.vx*=Math.pow(.001,dt);player.vx=clamp(player.vx,-280,280);
    if((input.keys.has(' ')||input.keys.has('w')||input.keys.has('arrowup')||input.touch.has('up'))&&player.grounded){player.vy=-520;player.grounded=false;sound(130,.05,'sine',.01)}
    player.vy+=1450*dt;player.x=clamp(player.x+player.vx*dt,0,WORLD-player.w);player.y+=player.vy*dt;if(player.y+player.h>=FLOOR){player.y=FLOOR-player.h;player.vy=0;player.grounded=true}
    if((input.mouse.down||input.mobileFire)&&state==='playing')shoot();
