.mobile-controls{align-items:flex-end;gap:12px;padding:0 4%;bottom:4%;touch-action:none;user-select:none;-webkit-user-select:none}
.move-controls{display:flex;align-items:flex-end;gap:8px;pointer-events:auto}
.move-controls button,.mobile-actions button{touch-action:none;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;box-shadow:0 4px 18px #0007;background:rgba(13,20,24,.82);border:1px solid rgba(168,190,181,.48);color:#e5ebe3;border-radius:8px;font:10px var(--mono);letter-spacing:.08em}
.move-controls button{width:54px;height:54px;font-size:17px}
.move-controls button:last-child{width:64px;font-size:9px;color:var(--cyan)}
.mobile-actions{display:grid;grid-template-columns:repeat(3,62px);gap:7px;align-items:end}
.mobile-actions button{width:62px;height:48px;font-size:8px}
.mobile-actions #mobileFire{height:58px;background:rgba(91,34,32,.9);border-color:#e45148;color:#fff0e8}
.mobile-actions #mobileUse{color:var(--cyan)}
.mobile-actions #mobilePause{font-size:17px;color:#e3e7df}
@media(max-width:700px){
 .title-screen{padding:6% 7% 8%}
 .title-top{font-size:8px}
 .title-copy{max-width:430px}
 .title-copy h1{font-size:clamp(58px,12vw,92px)}
 .title-copy .eyebrow{font-size:8px;margin-bottom:15px}
 .title-desc{font-size:10px;line-height:1.7;margin:17px 0 19px}
 .title-hint{font-size:8px;margin-top:12px}
 .title-bottom{font-size:7px}
 .hud-bottom{bottom:24%}
 .mobile-controls{gap:8px;padding:0 3%;bottom:4%}
 .move-controls{gap:5px}
 .move-controls button{width:46px;height:48px}
 .move-controls button:last-child{width:54px}
 .mobile-actions{grid-template-columns:repeat(3,54px);gap:5px}
 .mobile-actions button{width:54px;height:43px;font-size:7px}
 .mobile-actions #mobileFire{height:52px}
}
@media(max-width:700px) and (orientation:portrait){.title-copy h1{font-size:clamp(54px,10vw,78px)}}

